    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(n):
        grid.append(next(iterator))

    # Convert to a mutable list of lists
    board = [list(row) for row in grid]

    # Directions for the 4 neighbors relative to the center (0,0)
    # We will try to place a piece with its center at (r, c)
    # The offsets for the 5 cells are:
    # (-1, 0), (0, -1), (1, 0), (0, 1), (0, 0)
    offsets = [(-1, 0), (0, -1), (1, 0), (0, 1), (0, 0)]

    def can_place(r, c):
        # Check boundaries for center
        if r < 1 or r >= n - 1 or c < 1 or c >= n - 1:
            return False

        # Check if all 5 cells are free
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < n and 0 <= nc < n):
                return False
            if board[nr][nc] == '#':
                return False
        return True

    def place_piece(r, c):
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            board[nr][nc] = '#'

    def remove_piece(r, c):
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            board[nr][nc] = '.'

    def is_full():
        for r in range(n):
            for c in range(n):
                if board[r][c] == '.':
                    return False
        return True

    def dfs(idx):
        if idx == n * n:
            return True

        r, c = idx // n, idx % n

        if board[r][c] == '#':
            return dfs(idx + 1)

        # Try to place a piece with center at (r+1, c+1) such that it covers (r, c)
        # The cell (r, c) is one of the 4 neighbors.
        # Let's map (r, c) to which neighbor position it corresponds to relative to center (cr, cc).
        # Neighbor offsets: (-1,0) -> top, (0,-1) -> left, (1,0) -> bottom, (0,1) -> right.
        # If (r, c) is top neighbor: center is (r+1, c)
        # If (r, c) is left neighbor: center is (r, c+1)
        # If (r, c) is bottom neighbor: center is (r-1, c)
        # If (r, c) is right neighbor: center is (r, c-1)

        # Determine possible centers that cover (r, c)
        candidates = []

        # Case 1: (r, c) is the top neighbor of center (r+1, c)
        if r + 1 < n and c >= 1 and c < n - 1:
            candidates.append((r + 1, c))

        # Case 2: (r, c) is the left neighbor of center (r, c+1)
        if r >= 1 and r < n - 1 and c + 1 < n:
            candidates.append((r, c + 1))

        # Case 3: (r, c) is the bottom neighbor of center (r-1, c)
        if r - 1 >= 1 and c >= 1 and c < n - 1:
            candidates.append((r - 1, c))

        # Case 4: (r, c) is the right neighbor of center (r, c-1)
        if r >= 1 and r < n - 1 and c - 1 >= 1:
            candidates.append((r, c - 1))

        # We need to check if any of these candidates can form a valid piece covering (r,c)
        # But note: the piece must cover exactly the 5 cells defined by the center and its 4 neighbors.
        # So if we pick a center, the set of covered cells is fixed.
        # We just need to ensure that (r,c) is in that set (which we enforced by generating candidates)
        # and that all other cells in the set are free and within bounds.

        # However, there is a catch: multiple centers might cover (r,c). We must try all valid ones.
        # But wait, the problem says we fill the board completely. The order matters for backtracking.
        # We are at (r,c) which is currently '.'. We MUST cover it.
        # So we try all possible centers that would cover (r,c) and see if placing a piece works.

        # Sort candidates to have deterministic behavior (though not strictly necessary)
        # candidates.sort()

        for cr, cc in candidates:
            if can_place(cr, cc):
                place_piece(cr, cc)
                if dfs(idx + 1):
                    return True
                remove_piece(cr, cc)

        return False

    if dfs(0):
        print("YES")
    else:
        print("NO")

