def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    grid = []
    for i in range(n):
        grid.append(list(input_data[1 + i]))

    # Directions for the 4 arms relative to the center (up, right, down, left)
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    def can_place(r, c):
        # Check if a piece with center at (r, c) fits entirely within bounds
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= n or nc < 0 or nc >= n:
                return False
        return True

    def try_fill(r, c):
        # Check if all 5 cells (center + 4 neighbors) are currently free ('.')
        for dr, dc in [(0, 0)] + directions:
            nr, nc = r + dr, c + dc
            if grid[nr][nc] != '.':
                return False
        return True

    def apply_fill(r, c):
        # Mark center and 4 neighbors as occupied
        grid[r][c] = '#'
        for dr, dc in directions:
            grid[r + dr][c + dc] = '#'

    def remove_fill(r, c):
        # Unmark center and 4 neighbors
        grid[r][c] = '.'
        for dr, dc in directions:
            grid[r + dr][c + dc] = '.'

    def backtrack(idx):
        # idx represents the current cell index being considered: r * n + c
        r = idx // n
        c = idx % n

        # If we've processed all cells, we are done
        if idx == n * n:
            return True

        # If current cell is already occupied, move to next
        if grid[r][c] == '#':
            return backtrack(idx + 1)

        # If current cell is free, it MUST be covered.
        # Since each piece has exactly one center and four arms, and every cell must be covered,
        # a free cell must be the center of a new piece OR an arm of an existing piece.
        # However, we are processing in raster order. If grid[r][c] is '.', it cannot be an arm 
        # of a piece centered above or to the left because those decisions were already made 
        # and would have marked this cell as '#'.
        # Therefore, if we encounter a free cell, it MUST be the center of a new piece.

        # Check if we can place a piece here
        if not can_place(r, c):
            return False

        if not try_fill(r, c):
            return False

        # Place the piece
        apply_fill(r, c)

        # Recurse
        if backtrack(idx + 1):
            return True

        # Backtrack: remove the piece
        remove_fill(r, c)

        return False

    if backtrack(0):
        print("YES")
    else:
        print("NO")

