        return 0 <= r < n and 0 <= c < n

    def can_place_piece(r, c):
        # Try to place a piece with center at (r, c)
        # Check all 5 cells
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            if not is_valid(nr, nc):
                return False
            if board[nr][nc] == '#':
                return False
        return True

    def place_piece(r, c):
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            board[nr][nc] = '#'

    def remove_piece(r, c):
        for dr, dc in offsets:
            nr, nc = r + dr, c + dc
            board[nr][nc] = '.'

    def count_free():
        count = 0
        for r in range(n):
